        parameters ??= new Dictionary<string, object>();
        IList<object> currencyTypeparamsCurrencyTypeVariable = (IList<object>)this.handleOptionStringAndParams(parameters, "fetchWithdrawals", "currencyType");
        string? currencyType = (string)currencyTypeparamsCurrencyTypeVariable[0];
        var paramsCurrencyType = currencyTypeparamsCurrencyTypeVariable[1];
        if ((currencyType == "crypto"))
        {
            List<object> results = ccxt.BaseExchange.FromTransactionList(await this.FetchTransactionsWithMethod("v2PrivateGetAccountsAccountIdTransactions",code,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), paramsCurrencyType));
            return ccxt.BaseExchange.ToTransactionList(this.filterByArray(results, "type", "withdrawal", false));
        }
        return await this.FetchTransactionsWithMethod("v2PrivateGetAccountsAccountIdWithdrawals",code,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), paramsCurrencyType);
    }

    /**
     * @method
     * @name coinbase#fetchDeposits
     * @description Fetch all fiat deposits made to an account. Won't return crypto deposits or staking rewards. Use fetchLedger for those.
     * @see https://docs.cdp.coinbase.com/coinbase-app/transfer-apis/deposit-fiat
     * @see https://docs.cdp.coinbase.com/coinbase-app/track-apis/transactions
     * @param {string} code unified currency code
     * @param {int} [since] the earliest time in ms to fetch deposits for
     * @param {int} [limit] the maximum number of deposits structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.currencyType] "fiat" or "crypto"
     * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<List<ccxt.Transaction>> FetchDeposits(string code = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IList<object> currencyTypeparamsCurrencyTypeVariable = (IList<object>)this.handleOptionStringAndParams(parameters, "fetchDeposits", "currencyType");
        string? currencyType = (string)currencyTypeparamsCurrencyTypeVariable[0];
        var paramsCurrencyType = currencyTypeparamsCurrencyTypeVariable[1];
        if ((currencyType == "crypto"))
        {
            List<object> results = ccxt.BaseExchange.FromTransactionList(await this.FetchTransactionsWithMethod("v2PrivateGetAccountsAccountIdTransactions",code,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), paramsCurrencyType));
            return ccxt.BaseExchange.ToTransactionList(this.filterByArray(results, "type", "deposit", false));
        }
        return await this.FetchTransactionsWithMethod("v2PrivateGetAccountsAccountIdDeposits",code,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), paramsCurrencyType);
    }

    /**
     * @method
     * @name coinbase#fetchDepositsWithdrawals
     * @description fetch history of deposits and withdrawals
     * @see https://docs.cdp.coinbase.com/coinbase-app/track-apis/transactions
     * @param {string} [code] unified currency code for the currency of the deposit/withdrawals, default is undefined
     * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal, default is undefined
     * @param {int} [limit] max number of deposit/withdrawals to return, default = 50, Min: 1, Max: 100
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a list of [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<List<ccxt.Transaction>> FetchDepositsWithdrawals(string code = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        List<object> results = ccxt.BaseExchange.FromTransactionList(await this.FetchTransactionsWithMethod("v2PrivateGetAccountsAccountIdTransactions",code,ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), parameters));
        return ccxt.BaseExchange.ToTransactionList(this.filterByArray(results, "type", new List<object>() {"deposit", "withdrawal"}, false));
    }

    public virtual string? parseTransactionStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "created", "pending" },
            { "completed", "ok" },
            { "canceled", "canceled" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Dictionary<string, object> parseTransaction(object transaction, object currency = null)
    {
        //
        // fiat deposit
        //
        //     {
        //         "id": "f34c19f3-b730-5e3d-9f72",
        //         "status": "completed",
        //         "payment_method": {
        //             "id": "a022b31d-f9c7-5043-98f2",
        //             "resource": "payment_method",
        //             "resource_path": "/v2/payment-methods/a022b31d-f9c7-5043-98f2"
        //         },
        //         "transaction": {
        //             "id": "04ed4113-3732-5b0c-af86-b1d2146977d0",
        //             "resource": "transaction",
        //             "resource_path": "/v2/accounts/91cd2d36-3a91-55b6-a5d4-0124cf105483/transactions/04ed4113-3732-5b0c-af86"
        //         },
        //         "user_reference": "2VTYTH",
        //         "created_at": "2017-02-09T07:01:18Z",
        //         "updated_at": "2017-02-09T07:01:26Z",
        //         "resource": "deposit",
        //         "resource_path": "/v2/accounts/91cd2d36-3a91-55b6-a5d4-0124cf105483/deposits/f34c19f3-b730-5e3d-9f72",
        //         "committed": true,
        //         "payout_at": "2017-02-12T07:01:17Z",
        //         "instant": false,
        //         "fee": { "amount": "0.00", "currency": "EUR" },
        //         "amount": { "amount": "114.02", "currency": "EUR" },
        //         "subtotal": { "amount": "114.02", "currency": "EUR" },
        //         "hold_until": null,
        //         "hold_days": 0,
        //         "hold_business_days": 0,
        //         "next_step": null
        //     }
        //
        // fiat_withdrawal
        //
        //     {
        //         "id": "cfcc3b4a-eeb6-5e8c-8058",
        //         "status": "completed",
        //         "payment_method": {
        //             "id": "8b94cfa4-f7fd-5a12-a76a",
        //             "resource": "payment_method",
        //             "resource_path": "/v2/payment-methods/8b94cfa4-f7fd-5a12-a76a"
        //         },
        //         "transaction": {
        //             "id": "fcc2550b-5104-5f83-a444",
        //             "resource": "transaction",
        //             "resource_path": "/v2/accounts/91cd2d36-3a91-55b6-a5d4-0124cf105483/transactions/fcc2550b-5104-5f83-a444"
        //         },
        //         "user_reference": "MEUGK",
        //         "created_at": "2018-07-26T08:55:12Z",
        //         "updated_at": "2018-07-26T08:58:18Z",
        //         "resource": "withdrawal",
        //         "resource_path": "/v2/accounts/91cd2d36-3a91-55b6-a5d4-0124cf105483/withdrawals/cfcc3b4a-eeb6-5e8c-8058",
        //         "committed": true,
        //         "payout_at": "2018-07-31T08:55:12Z",
        //         "instant": false,
        //         "fee": { "amount": "0.15", "currency": "EUR" },
        //         "amount": { "amount": "13130.69", "currency": "EUR" },
        //         "subtotal": { "amount": "13130.84", "currency": "EUR" },
        //         "idem": "e549dee5-63ed-4e79-8a96",
        //         "next_step": null
        //     }
        //
        // withdraw
        //
        //     {
        //         "id": "a1794ecf-5693-55fa-70cf-ef731748ed82",
        //         "type": "send",
        //         "status": "pending",
        //         "amount": {
        //             "amount": "-14.008308",
        //             "currency": "USDC"
        //         },
        //         "native_amount": {
        //             "amount": "-18.74",
        //             "currency": "CAD"
        //         },
        //         "description": null,
        //         "created_at": "2024-01-12T01:27:31Z",
        //         "updated_at": "2024-01-12T01:27:31Z",
        //         "resource": "transaction",
        //         "resource_path": "/v2/accounts/a34bgfad-ed67-538b-bffc-730c98c10da0/transactions/a1794ecf-5693-55fa-70cf-ef731748ed82",
        //         "instant_exchange": false,
        //         "network": {
        //             "status": "pending",
        //             "status_description": "Pending (est. less than 10 minutes)",
        //             "transaction_fee": {
        //                 "amount": "4.008308",
        //                 "currency": "USDC"
        //             },
        //             "transaction_amount": {
        //                 "amount": "10.000000",
        //                 "currency": "USDC"
        //             },
        //             "confirmations": 0
        //         },
        //         "to": {
        //             "resource": "ethereum_address",
        //             "address": "0x9...",
        //             "currency": "USDC",
        //             "address_info": {
        //                 "address": "0x9..."
        //             }
        //         },
        //         "idem": "748d8591-dg9a-7831-a45b-crd61dg78762",
        //         "details": {
        //             "title": "Sent USDC",
        //             "subtitle": "To USDC address on Ethereum network",
        //             "header": "Sent 14.008308 USDC ($18.74)",
        //             "health": "warning"
        //         },
        //         "hide_native_amount": false
        //     }
        //
        //
        // crypto deposit & withdrawal (using `/transactions` endpoint)
        //    {
        //        "amount": {
        //            "amount": "0.00014200", (negative for withdrawal)
        //            "currency": "BTC"
        //        },
        //        "created_at": "2024-03-29T15:48:30Z",
        //        "id": "0031a605-241d-514d-a97b-d4b99f3225d3",
        //        "idem": "092a979b-017e-4403-940a-2ca57811f442", // field present only in case of withdrawal
        //        "native_amount": {
        //            "amount": "9.85", (negative for withdrawal)
        //            "currency": "USD"
        //        },
        //        "network": {
        //            "status": "pending", // if status is `off_blockchain` then no more other fields are present in this object
        //            "hash": "5jYuvrNsvX2DZoMnzGYzVpYxJLfYu4GSK3xetG1H5LHrSovsuFCFYdFMwNRoiht3s6fBk92MM8QLLnz65xuEFTrE",
        //            "network_name": "solana",
        //            "transaction_fee": {
        //                "amount": "0.000100000",
        //                "currency": "SOL"
        //            }
        //        },
        //        "resource": "transaction",
        //        "resource_path": "/v2/accounts/dc504b1c-248e-5b68-a3b0-b991f7fa84e6/transactions/0031a605-241d-514d-a97b-d4b99f3225d3",
        //        "status": "completed",
        //        "type": "send",
        //        "from": { // in some cases, field might be present for deposit
        //            "id": "7fd10cd7-b091-5cee-ba41-c29e49a7cccf",
        //            "name": "Coinbase",
        //            "resource": "user"
        //        },
        //        "to": { // field only present for withdrawal
        //            "address": "5HA12BNthAvBwNYARYf9y5MqqCpB4qhCNFCs1Qw48ACE",
        //            "resource": "address"
        //        },
        //        "description": "C3 - One Time BTC Credit . Reference Case # 123.", //  in some cases, field might be present for deposit
        //    }
        //
        string? transactionType = this.safeString(transaction, "type");
        IDictionary<string, object> amountAndCurrencyObject = null;
        IDictionary<string, object> feeObject = null;
        IDictionary<string, object> network = this.safeDict(transaction, "network", new Dictionary<string, object>() {});
        if (transactionType == "send")
        {
            amountAndCurrencyObject = this.safeDict(network, "transaction_amount");
            feeObject = this.safeDict(network, "transaction_fee", new Dictionary<string, object>() {});
        } else
        {
            amountAndCurrencyObject = this.safeDict(transaction, "subtotal");
            feeObject = this.safeDict(transaction, "fee", new Dictionary<string, object>() {});
        }
        if ((amountAndCurrencyObject == null))
        {
            amountAndCurrencyObject = this.safeDict(transaction, "amount");
        }
        string? amountString = this.safeString(amountAndCurrencyObject, "amount");
        string? amountStringAbs = Precise.stringAbs(amountString);
        string? status = this.parseTransactionStatus(this.safeString(transaction, "status"));
        if ((status == null))
        {
            bool? committed = this.safeBool(transaction, "committed");
            status = ((committed == true)) ? "ok" : "pending";
        }
        string? id = this.safeString(transaction, "id");
        string? currencyId = this.safeString(amountAndCurrencyObject, "currency");
        string? feeCurrencyId = this.safeString(feeObject, "currency");
        string? datetime = this.safeString(transaction, "created_at");
        string? resource = this.safeString(transaction, "resource");
        string? type = resource;
        if (!this.inArray(type, new List<object>() {"deposit", "withdrawal"}))
        {
            if (Precise.stringGt(amountString, "0"))
            {
                type = "deposit";
            } else if (Precise.stringLt(amountString, "0"))
            {
                type = "withdrawal";
            }
        }
        IDictionary<string, object> toObject = this.safeDict(transaction, "to");
        string? addressTo = this.safeString(toObject, "address");
        string? networkId = this.safeString(network, "network_name");
        string? code = this.safeCurrencyCode(currencyId, currency);
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", id },
            { "txid", this.safeString(network, "hash", id) },
            { "timestamp", this.parse8601(datetime) },
            { "datetime", datetime },
            { "network", this.networkIdToCode(networkId, code) },
            { "address", addressTo },
            { "addressTo", addressTo },
            { "addressFrom", null },
            { "tag", null },
            { "tagTo", null },
            { "tagFrom", null },
            { "type", type },
            { "amount", this.parseNumber(amountStringAbs) },
            { "currency", code },
            { "status", status },
            { "updated", this.parse8601(this.safeString(transaction, "updated_at")) },
            { "fee", new Dictionary<string, object>() {
                { "cost", this.safeNumber(feeObject, "amount") },
                { "currency", this.safeCurrencyCode(feeCurrencyId) },
            } },
        };
    }

    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // fetchMyBuys, fetchMySells
        //
        //     {
        //         "id": "67e0eaec-07d7-54c4-a72c-2e92826897df",
        //         "status": "completed",
        //         "payment_method": {
        //             "id": "83562370-3e5c-51db-87da-752af5ab9559",
        //             "resource": "payment_method",
        //             "resource_path": "/v2/payment-methods/83562370-3e5c-51db-87da-752af5ab9559"
        //         },
        //         "transaction": {
        //             "id": "441b9494-b3f0-5b98-b9b0-4d82c21c252a",
        //             "resource": "transaction",
        //             "resource_path": "/v2/accounts/2bbf394c-193b-5b2a-9155-3b4732659ede/transactions/441b9494-b3f0-5b98-b9b0-4d82c21c252a"
        //         },
        //         "amount": { "amount": "1.00000000", "currency": "BTC" },
        //         "total": { "amount": "10.25", "currency": "USD" },
        //         "subtotal": { "amount": "10.10", "currency": "USD" },
        //         "created_at": "2015-01-31T20:49:02Z",
        //         "updated_at": "2015-02-11T16:54:02-08:00",
        //         "resource": "buy",
        //         "resource_path": "/v2/accounts/2bbf394c-193b-5b2a-9155-3b4732659ede/buys/67e0eaec-07d7-54c4-a72c-2e92826897df",
        //         "committed": true,
        //         "instant": false,
        //         "fee": { "amount": "0.15", "currency": "USD" },
        //         "payout_at": "2015-02-18T16:54:00-08:00"
        //     }
        //
        // fetchTrades
        //
        //     {
        //         "trade_id": "10092327",
        //         "product_id": "BTC-USDT",
        //         "price": "17488.12",
        //         "size": "0.0000623",
        //         "time": "2023-01-11T00:52:37.557001Z",
        //         "side": "BUY",
        //         "bid": "",
        //         "ask": ""
        //     }
        //
        // fetchMyTrades
        //
        //     {
        //         "entry_id": "b88b82cc89e326a2778874795102cbafd08dd979a2a7a3c69603fc4c23c2e010",
        //         "trade_id": "cdc39e45-bbd3-44ec-bf02-61742dfb16a1",
        //         "order_id": "813a53c5-3e39-47bb-863d-2faf685d22d8",
        //         "trade_time": "2023-01-18T01:37:38.091377090Z",
        //         "trade_type": "FILL",
        //         "price": "21220.64",
        //         "size": "0.0046830664333996",
        //         "commission": "0.0000280983986004",
        //         "product_id": "BTC-USDT",
        //         "sequence_timestamp": "2023-01-18T01:37:38.092520Z",
        //         "liquidity_indicator": "UNKNOWN_LIQUIDITY_INDICATOR",
        //         "size_in_quote": true,
        //         "user_id": "1111111-1111-1111-1111-111111111111",
        //         "side": "BUY"
        //     }
        //
        object symbol = null;
        IDictionary<string, object> totalObject = this.safeDict(trade, "total", new Dictionary<string, object>() {});
        IDictionary<string, object> amountObject = this.safeDict(trade, "amount", new Dictionary<string, object>() {});
        IDictionary<string, object> subtotalObject = this.safeDict(trade, "subtotal", new Dictionary<string, object>() {});
        IDictionary<string, object> feeObject = this.safeDict(trade, "fee", new Dictionary<string, object>() {});
        string? marketId = this.safeString(trade, "product_id");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, "-");
        if ((marketResolved != null))
        {
            symbol = GetValue(marketResolved, "symbol");
        } else
        {
            string? baseId = this.safeString(amountObject, "currency");
            string? quoteId = this.safeString(totalObject, "currency");
            if (((baseId != null)) && ((quoteId != null)))
            {
                object bs = this.safeCurrencyCode(baseId);
                string? quote = this.safeCurrencyCode(quoteId);
                symbol = add(add(bs, "/"), quote);
            }
        }
        bool? sizeInQuote = this.safeBool(trade, "size_in_quote");
        string? v3Price = this.safeString(trade, "price");
        string? v3Cost = null;
        string? v3Amount = this.safeString(trade, "size");
        if ((sizeInQuote == true))
        {
            // calculate base size
            v3Cost = v3Amount;
            v3Amount = Precise.stringDiv(v3Amount, v3Price);
        }
        string? v3FeeCost = this.safeString(trade, "commission");
        string? amountString = this.safeString(amountObject, "amount", v3Amount);
        string? costString = this.safeString(subtotalObject, "amount", v3Cost);
        string? priceString = null;
        string? cost = null;
        if (((costString != null)) && ((amountString != null)))
        {
            priceString = Precise.stringDiv(costString, amountString);
        } else
        {
            priceString = v3Price;
        }
        if (((priceString != null)) && ((amountString != null)))
        {
            cost = Precise.stringMul(priceString, amountString);
        } else
        {
            cost = costString;
        }
        string? feeCurrencyId = this.safeString(feeObject, "currency");
        double? feeCost = this.safeNumber(feeObject, "amount", this.parseNumber(v3FeeCost));
        if (((feeCurrencyId == null)) && ((marketResolved != null)) && ((feeCost != null)))
        {
            feeCurrencyId = this.safeString(marketResolved, "quote");
        }
        string? datetime = this.safeStringN(trade, new List<object>() {"created_at", "trade_time", "time"});
        string? side = this.safeStringLower2(trade, "resource", "side");
        string? takerOrMaker = this.safeStringLower(trade, "liquidity_indicator");
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeString2(trade, "id", "trade_id") },
            { "order", this.safeString(trade, "order_id") },
            { "timestamp", this.parse8601(datetime) },
            { "datetime", datetime },
            { "symbol", symbol },
            { "type", null },
            { "side", (side == "unknown_order_side") ? null : side },
            { "takerOrMaker", (takerOrMaker == "unknown_liquidity_indicator") ? null : takerOrMaker },
            { "price", priceString },
            { "amount", amountString },
            { "cost", cost },
            { "fee", new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", this.safeCurrencyCode(feeCurrencyId) },
            } },
        });
    }

    /**
     * @method
     * @name coinbase#fetchMarkets
     * @see https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/products/list-products
     * @see https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/public/list-public-products
     * @see https://docs.cdp.coinbase.com/coinbase-app/track-apis/currencies
     * @see https://docs.cdp.coinbase.com/coinbase-app/track-apis/exchange-rates
     * @description retrieves data on all markets for coinbase
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.usePrivate] use private endpoint for fetching markets
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.safeBool(this.options, "adjustForTimeDifference") == true))
        {
            await this.loadTimeDifference();
        }
        string? method = this.safeString(this.options, "fetchMarkets", "fetchMarketsV3");
        if (method == "fetchMarketsV3")
        {
            return await this.FetchMarketsV3(parameters);
        }
        return await this.FetchMarketsV2(parameters);
    }

    public async virtual Task<List<ccxt.MarketInterface>> FetchMarketsV2(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = ccxt.BaseExchange.FromDict(await this.FetchCurrenciesFromCache(parameters));
        IDictionary<string, object> currencies = this.safeDict(response, "currencies", new Dictionary<string, object>() {});
        IDictionary<string, object> exchangeRates = this.safeDict(response, "exchangeRates", new Dictionary<string, object>() {});
        List<object> data = this.safeList(currencies, "data", new List<object>() {});
        Dictionary<string, object> dataById = this.indexBy(data, "id");
        IDictionary<string, object> rates = this.safeDict(this.safeDict(exchangeRates, "data", new Dictionary<string, object>() {}), "rates", new Dictionary<string, object>() {});
        List<object> baseIds = new List<object>(((IDictionary<string,object>)rates).Keys);
        List<object> result = new List<object>() {};
        for (int i = 0; i < baseIds.Count; i++)
        {
            object baseId = baseIds[i];
            string? bs = this.safeCurrencyCode(baseId);
            if ((bs == null))
            {
                continue;
            }
            string type = "crypto";
            if (inOp(dataById, baseId))
            {
                type = "fiat";
            }
            // https://github.com/ccxt/ccxt/issues/6066
            if (type == "crypto")
            {
                for (int j = 0; j < data.Count; j++)
                {
                    object quoteCurrency = data[j];
                    string? quoteId = this.safeString(quoteCurrency, "id");
                    string? quote = this.safeCurrencyCode(quoteId);
                    if ((quote == null))
                    {
                        continue;
                    }
                    result.Add(this.safeMarketStructure(new Dictionary<string, object>() {
                        { "id", add(add(baseId, "-"), quoteId) },
                        { "symbol", ((bs + "/") + quote) },
                        { "base", bs },
                        { "quote", quote },
                        { "settle", null },
                        { "baseId", baseId },
                        { "quoteId", quoteId },
